// Some portions generated by Codex
// @ts-check
const fs = require('node:fs/promises');
const path = require('node:path');
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('graph-persistence');
const OTHER_REPOSITORY_ID = uniqueRepositoryId('graph-persistence-other');
const EX = 'http://example.org/persistence/';
const GRAPH_DATA = `
@prefix ex: <http://example.org/persistence/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
ex:alice a ex:Person, ex:Manager ; rdfs:label "Alice" ; ex:age 39 ; ex:worksFor ex:acme .
ex:bob a ex:Person ; rdfs:label "Bob" ; ex:age 34 ; ex:worksFor ex:acme .
ex:carol a ex:Person, ex:Manager ; rdfs:label "Carol" ; ex:age 46 ; ex:worksFor ex:globex .
ex:dave a ex:Person ; rdfs:label "Dave" ; ex:age 29 .
ex:acme a ex:Organization ; rdfs:label "Acme" ; ex:founded "1999-04-01"^^xsd:date .
ex:globex a ex:Organization ; rdfs:label "Globex" ; ex:founded "2005-10-10"^^xsd:date .
`;
const EVIDENCE_DIRECTORY = process.env.GRAPH_PERSISTENCE_EVIDENCE_DIR || '/private/tmp/graph-persistence-qa';

async function createRepository(request, repositoryId) {
    const url = `${serverBaseUrl()}/repositories/${encodeURIComponent(repositoryId)}`;
    const existing = await request.get(url);
    if (![400, 404].includes(existing.status())) {
        throw new Error(`Refusing to use non-absent disposable repository ${repositoryId}: GET ${existing.status()}`);
    }
    const created = await request.put(url, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(repositoryId, 'Graph persistence fixture')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${url}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: GRAPH_DATA
    });
    expect([200, 204]).toContain(loaded.status());
}

test.beforeAll(async ({ request }) => {
    await createRepository(request, REPOSITORY_ID);
    await createRepository(request, OTHER_REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
    await deleteRepository(request, serverBaseUrl(), OTHER_REPOSITORY_ID);
});

test.beforeEach(async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
});

const explorerOf = (page) => page.locator('.graph-explorer');
const toolsOf = (page) => explorerOf(page).locator('summary[aria-label="Open workspace tools"]');
const dialogOf = (page, name) => page.getByRole('dialog', { name });

async function openGraph(page, repositoryId = REPOSITORY_ID) {
    await page.goto(repositoryPageUrl(repositoryId, 'graph'));
    await waitForRoute(page, 'graph');
    return explorerOf(page);
}

async function loadGraph(page, repositoryId = REPOSITORY_ID) {
    const explorer = await openGraph(page, repositoryId);
    const alice = nodeByLabel(explorer, 'Alice');
    const load = explorer.getByRole('button', { name: /^Load \d+ statements$/ });
    await expect.poll(async () => (await alice.count()) > 0 || await load.isVisible(), { timeout: 30000 }).toBe(true);
    if (await alice.count() === 0) await load.click();
    await expect(alice).toBeAttached({ timeout: 30000 });
    return explorer;
}

async function openTool(page, action) {
    await toolsOf(page).click();
    const button = explorerOf(page).getByRole('button', { name: action, exact: true });
    await expect(button).toBeVisible();
    await button.click();
}

async function saveGraph(page, name, options = {}) {
    await openTool(page, options.download ? 'Save and download' : 'Save in browser');
    const dialog = dialogOf(page, 'Save graph');
    await expect(dialog).toBeVisible();
    await dialog.getByLabel('Graph name').fill(name);
    if (options.saveAsNew) {
        await dialog.getByLabel('Save as new').check();
    }
    let download;
    if (options.download) {
        [download] = await Promise.all([
            page.waitForEvent('download'),
            dialog.getByRole('button', { name: 'Save and download', exact: true }).click()
        ]);
    } else {
        await dialog.getByRole('button', { name: 'Save', exact: true }).click();
    }
    await expect(dialog).toBeHidden();
    return download;
}

async function openLibrary(page) {
    await openTool(page, 'Open from browser');
    const dialog = dialogOf(page, 'Open saved graph');
    await expect(dialog).toBeVisible();
    await expect(dialog.getByText('Loading saved graphs…')).toBeHidden();
    return dialog;
}

function libraryRow(dialog, name) {
    const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return dialog.locator('.workspace-library-item').filter({ hasText: new RegExp(`^${escapedName}(?=\\d|$)`) });
}

async function openSavedGraph(page, name) {
    const library = await openLibrary(page);
    const row = libraryRow(library, name);
    await expect(row).toBeVisible();
    await row.getByRole('button', { name: 'Open', exact: true }).click();
    const replace = dialogOf(page, 'Open graph');
    await expect(replace).toBeVisible();
    await replace.getByRole('button', { name: 'Open without saving', exact: true }).click();
    await expect(replace).toBeHidden();
}

async function chooseFile(page, file) {
    const [chooser] = await Promise.all([
        page.waitForEvent('filechooser'),
        openTool(page, 'Load and open')
    ]);
    await chooser.setFiles(file);
}

async function loadReplacement(page, file) {
    await chooseFile(page, file);
    const dialog = dialogOf(page, 'Open graph');
    await expect(dialog).toBeVisible();
    return dialog;
}

function nodeByLabel(explorer, label) {
    return explorer.locator('.graph-node').filter({ hasText: label }).first();
}

