test('named snapshots persist per stable server and repository, support CRUD, and allow 256-character names', async ({ page }) => {
    const explorer = await loadGraph(page);
    const app = page.locator('#workbench-app');
    const serverIdentity = await app.getAttribute('data-workbench-server-identity');
    expect(serverIdentity).toMatch(/^sha256:[a-f0-9]{64}/);

    await saveGraph(page, 'Named graph');
    await page.reload();
    await waitForRoute(page, 'graph');
    await expect(page.locator('#workbench-app')).toHaveAttribute('data-workbench-server-identity', serverIdentity);
    const library = await openLibrary(page);
    const row = libraryRow(library, 'Named graph');
    await expect(row).toBeVisible();
    await row.getByRole('button', { name: 'Rename', exact: true }).click();
    const rename = library.getByRole('form', { name: 'Rename Named graph' });
    await rename.getByLabel('Graph name').fill('Renamed graph');
    await rename.getByRole('button', { name: 'Rename graph', exact: true }).click();
    await expect(libraryRow(library, 'Renamed graph')).toBeVisible();

    const other = await openGraph(page, OTHER_REPOSITORY_ID);
    await toolsOf(page).click();
    await explorerOf(page).getByRole('button', { name: 'Open from browser', exact: true }).click();
    const isolatedLibrary = dialogOf(page, 'Open saved graph');
    await expect(isolatedLibrary.getByText('No saved graphs yet.')).toBeVisible();
    await isolatedLibrary.getByRole('button', { name: 'Close open saved graph', exact: true }).click();
    await expect(isolatedLibrary).toBeHidden();
    await expect(other.locator('.graph-node')).toHaveCount(0);

    await openGraph(page, REPOSITORY_ID);
    await loadGraph(page);
    const maximumName = 'G'.repeat(256);
    await saveGraph(page, maximumName);
    const maxLibrary = await openLibrary(page);
    await expect(libraryRow(maxLibrary, maximumName)).toBeVisible();
    const maxRow = libraryRow(maxLibrary, maximumName);
    await maxRow.getByRole('button', { name: 'Delete', exact: true }).click();
    const confirmation = maxLibrary.getByRole('region', { name: `Delete ${maximumName}` });
    await confirmation.getByRole('button', { name: 'Delete saved graph', exact: true }).click();
    await expect(libraryRow(maxLibrary, maximumName)).toHaveCount(0);

    const renamed = libraryRow(maxLibrary, 'Renamed graph');
    await expect(renamed).toBeVisible();
    await renamed.getByRole('button', { name: 'Delete', exact: true }).click();
    await maxLibrary.getByRole('region', { name: 'Delete Renamed graph' })
        .getByRole('button', { name: 'Delete saved graph', exact: true }).click();
    await expect(libraryRow(maxLibrary, 'Renamed graph')).toHaveCount(0);
});

