test('Save and download round-trips a workspace without changing its repository connection', async ({ page }) => {
    const explorer = await loadGraph(page);
    await explorer.getByRole('button', { name: 'Show all relation labels' }).click();
    const serverIdentity = await page.locator('#workbench-app').getAttribute('data-workbench-server-identity');
    const download = await saveGraph(page, 'Portable graph', { download: true });
    expect(download.suggestedFilename()).toBe('Portable graph.rdf4j-graph.json');
    await fs.mkdir(EVIDENCE_DIRECTORY, { recursive: true });
    const filePath = path.join(EVIDENCE_DIRECTORY, `${REPOSITORY_ID}-roundtrip.rdf4j-graph.json`);
    await download.saveAs(filePath);
    const envelope = JSON.parse(await fs.readFile(filePath, 'utf8'));
    expect(envelope.format).toBe('rdf4j-graph-workspace');
    expect(envelope.source.repositoryId).toBe(REPOSITORY_ID);
    expect(envelope.source.serverIdentity).toBe(serverIdentity.split(':').slice(0, 2).join(':'));

    await explorer.getByRole('button', { name: 'Show all relation labels' }).click();
    const opened = await loadReplacement(page, filePath);
    await opened.getByRole('button', { name: 'Open without saving', exact: true }).click();
    await expect(opened).toBeHidden();
    await expect(explorer.getByRole('button', { name: 'Show all relation labels' })).toHaveAttribute('aria-pressed', 'true');
    await expect(page.locator('#workbench-app')).toHaveAttribute('data-workbench-server-identity', serverIdentity);
    await expect(explorer.locator('.graph-node')).toHaveCount(6);
});

