test('Save current can branch its named view before replacement, and Undo restores the view and binding', async ({ page }) => {
    const explorer = await loadGraph(page);
    const values = explorer.getByRole('button', { name: 'Show values and types as nodes' });
    const labels = explorer.getByRole('button', { name: 'Show all relation labels' });
    await values.click();
    await labels.click();
    await explorer.getByRole('button', { name: /Filter graph nodes/ }).click();
    const filters = explorer.locator('#graph-filter-sidebar');
    await filters.locator('.facet-value', { hasText: 'Person' }).click();
    await nodeByLabel(explorer, 'Alice').click();
    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    const query = explorer.locator('#sparql');
    const startingQuery = 'SELECT ?s WHERE { ?s ?p ?o } # starting named view';
    await query.fill(startingQuery);
    await saveGraph(page, 'Starting graph');

    await values.click();
    await labels.click();
    await filters.locator('.filter-chips button', { hasText: 'Person' }).click();
    await filters.locator('.facet-value', { hasText: 'Organization' }).click();
    await nodeByLabel(explorer, 'Globex').click();
    const replacementQuery = 'SELECT ?s WHERE { ?s ?p ?o } # replacement named view';
    await query.fill(replacementQuery);
    await saveGraph(page, 'Replacement graph', { saveAsNew: true });

    await values.click();
    await labels.click();
    await filters.locator('.filter-chips button', { hasText: 'Organization' }).click();
    await filters.locator('.facet-value', { hasText: 'Manager' }).click();
    await nodeByLabel(explorer, 'Carol').click();
    const currentQuery = 'SELECT ?s WHERE { ?s ?p ?o } # current before replacement';
    await query.fill(currentQuery);

    const library = await openLibrary(page);
    const starting = libraryRow(library, 'Starting graph');
    await starting.getByRole('button', { name: 'Open', exact: true }).click();
    const replace = dialogOf(page, 'Open graph');
    await expect(replace.getByRole('button', { name: 'Save current', exact: true })).toBeEnabled();
    await replace.getByRole('button', { name: 'Save current', exact: true }).click();
    const save = dialogOf(page, 'Save graph');
    await expect(save.getByLabel('Graph name')).toHaveValue('Replacement graph');
    await save.getByLabel('Save as new').check();
    await save.getByLabel('Graph name').fill('Before replacement');
    await save.getByRole('button', { name: 'Save', exact: true }).click();
    await expect(save).toBeHidden();
    await expect(replace).toBeHidden();

    await expect(values).toHaveAttribute('aria-pressed', 'true');
    await expect(labels).toHaveAttribute('aria-pressed', 'true');
    await expect(filters.locator('.filter-chips button')).toHaveText(['Person']);
    await expect(query).toHaveValue(startingQuery);
    await expect(explorer.locator('.node-details h3')).toHaveText('Alice');

    const undo = explorer.getByRole('button', { name: 'Undo the last graph change' });
    await expect(undo).toBeEnabled();
    await undo.click();
    await expect(values).toHaveAttribute('aria-pressed', 'true');
    await expect(labels).toHaveAttribute('aria-pressed', 'true');
    await expect(filters.locator('.filter-chips button')).toHaveText(['Manager']);
    await expect(query).toHaveValue(currentQuery);
    await expect(explorer.locator('.node-details h3')).toHaveText('Carol');

    await openTool(page, 'Save in browser');
    const restoredBinding = dialogOf(page, 'Save graph');
    await expect(restoredBinding.getByLabel('Graph name')).toHaveValue('Before replacement');
    await expect(restoredBinding.getByLabel('Update existing')).toBeChecked();
    await restoredBinding.getByRole('button', { name: 'Cancel', exact: true }).click();
    await expect(restoredBinding).toBeHidden();
});

test('a pending query that finishes after opening a workspace cannot replace the opened graph', async ({ page }) => {
    const explorer = await loadGraph(page);
    const download = await saveGraph(page, 'Import target', { download: true });
    await fs.mkdir(EVIDENCE_DIRECTORY, { recursive: true });
    const filePath = path.join(EVIDENCE_DIRECTORY, `${REPOSITORY_ID}-pending-query.rdf4j-graph.json`);
    await download.saveAs(filePath);

    const pendingQuery = `CONSTRUCT { <${EX}late> <${EX}pending> <${EX}result> } WHERE {}`;
    const queryPath = new URL(repositoryPageUrl(REPOSITORY_ID, 'graph')).pathname;
    let startQuery;
    const queryStarted = new Promise((resolve) => { startQuery = resolve; });
    let releaseQuery;
    const queryGate = new Promise((resolve) => { releaseQuery = resolve; });
    let finishRoute;
    const routeFinished = new Promise((resolve) => { finishRoute = resolve; });
    const routeMatcher = (url) => new URL(url).pathname === queryPath;
    await page.route(routeMatcher, async (route) => {
        const request = route.request();
        if (request.method() !== 'POST' || request.postData() !== pendingQuery) {
            await route.continue();
            return;
        }
        startQuery();
        await queryGate;
        try {
            await route.fulfill({
                status: 200,
                contentType: 'application/sparql-results+json',
                body: JSON.stringify({
                    head: { vars: ['source', 'predicate', 'target'] },
                    results: { bindings: [{
                        source: { type: 'uri', value: `${EX}late` },
                        predicate: { type: 'uri', value: `${EX}pending` },
                        target: { type: 'uri', value: `${EX}result` }
                    }] }
                })
            });
        } finally {
            finishRoute();
        }
    });

    try {
        await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
        await explorer.locator('#sparql').fill(pendingQuery);
        await explorer.getByRole('button', { name: 'Run query', exact: true }).click();
        await queryStarted;

        const replace = await loadReplacement(page, filePath);
        await replace.getByRole('button', { name: 'Open without saving', exact: true }).click();
        await expect(replace).toBeHidden();
        await expect(explorer.locator('.graph-node')).toHaveCount(6);

        releaseQuery();
        await routeFinished;
        await expect(explorer.locator('.graph-node')).toHaveCount(6);
        await expect(nodeByLabel(explorer, 'Alice')).toBeAttached();
    } finally {
        releaseQuery();
        await page.unroute(routeMatcher);
    }
});

test('invalid, legacy, and foreign files leave the current graph unchanged until explicitly accepted', async ({ page }) => {
    const explorer = await loadGraph(page);
    await explorer.getByRole('button', { name: 'Show all relation labels' }).click();
    const unchangedCount = await explorer.locator('.graph-node').count();
    const invalid = await loadReplacement(page, { name: 'broken.json', mimeType: 'application/json', buffer: Buffer.from('{broken') });
    await expect(invalid.getByRole('alert')).toContainText('not valid workspace JSON');
    await expect(explorer.locator('.graph-node')).toHaveCount(unchangedCount);

    const [chooser] = await Promise.all([
        page.waitForEvent('filechooser'),
        invalid.getByRole('button', { name: 'Choose another file', exact: true }).click()
    ]);
    await chooser.setFiles([]);
    await page.locator('.workspace-library-file').evaluate((input) => input.dispatchEvent(new Event('cancel', { bubbles: true })));
    await invalid.getByRole('button', { name: 'Close open graph', exact: true }).click();
    await expect(invalid).toBeHidden();
    await expect(toolsOf(page)).toBeFocused();
    await expect(explorer.locator('.graph-node')).toHaveCount(unchangedCount);

    await saveGraph(page, 'Source graph', { download: true }).then(async (download) => {
        const filePath = path.join(EVIDENCE_DIRECTORY, `${REPOSITORY_ID}-source.rdf4j-graph.json`);
        await fs.mkdir(EVIDENCE_DIRECTORY, { recursive: true });
        await download.saveAs(filePath);
        const envelope = JSON.parse(await fs.readFile(filePath, 'utf8'));
        const legacy = JSON.stringify(envelope.workspace);
        const unknownSource = await loadReplacement(page, {
            name: 'legacy-workspace.json', mimeType: 'application/json', buffer: Buffer.from(legacy)
        });
        await expect(unknownSource.getByText(/does not identify its server and repository/)).toBeVisible();
        await expect(unknownSource.getByRole('button', { name: 'Open without saving', exact: true })).toBeDisabled();
        await unknownSource.getByRole('button', { name: 'Cancel', exact: true }).click();
        await expect(unknownSource).toBeHidden();
        await expect(explorer.locator('.graph-node')).toHaveCount(unchangedCount);

        envelope.source.repositoryId = OTHER_REPOSITORY_ID;
        const foreign = await loadReplacement(page, {
            name: 'foreign-graph.rdf4j-graph.json', mimeType: 'application/json', buffer: Buffer.from(JSON.stringify(envelope))
        });
        await expect(foreign.getByText(/different server or repository/)).toBeVisible();
        await foreign.getByRole('checkbox', { name: /I understand and want to open this graph here/ }).check();
        await expect(foreign.getByRole('button', { name: 'Open without saving', exact: true })).toBeEnabled();
        await foreign.getByRole('button', { name: 'Cancel', exact: true }).click();
        await expect(foreign).toBeHidden();
        await expect(explorer.locator('.graph-node')).toHaveCount(unchangedCount);
    });
});

test('a failed browser save offers a download-only fallback and can be retried', async ({ page }) => {
    await page.addInitScript(() => {
        window.__graphSnapshotWriteFailures = 0;
        const originalPut = IDBObjectStore.prototype.put;
        IDBObjectStore.prototype.put = function (...args) {
            if (this.name === 'snapshots' && window.__graphSnapshotWriteFailures > 0) {
                window.__graphSnapshotWriteFailures--;
                throw new DOMException('Injected storage quota failure', 'QuotaExceededError');
            }
            return originalPut.apply(this, args);
        };
    });
    await loadGraph(page);
    await page.evaluate(() => { window.__graphSnapshotWriteFailures = 1; });
    await openTool(page, 'Save and download');
    const dialog = dialogOf(page, 'Save graph');
    await dialog.getByLabel('Graph name').fill('Retryable graph');
    await dialog.getByRole('button', { name: 'Save and download', exact: true }).click();
    await expect(dialog.getByRole('alert')).toContainText('Injected storage quota failure');
    await expect(dialog.getByRole('button', { name: 'Download only', exact: true })).toBeVisible();
    const [fallback] = await Promise.all([
        page.waitForEvent('download'),
        dialog.getByRole('button', { name: 'Download only', exact: true }).click()
    ]);
    expect(fallback.suggestedFilename()).toBe('Retryable graph.rdf4j-graph.json');
    await expect(dialog).toBeHidden();

    const emptyLibrary = await openLibrary(page);
    await expect(emptyLibrary.getByText('No saved graphs yet.')).toBeVisible();
    await emptyLibrary.getByRole('button', { name: 'Close open saved graph', exact: true }).click();
    await saveGraph(page, 'Retryable graph');
    const savedLibrary = await openLibrary(page);
    await expect(libraryRow(savedLibrary, 'Retryable graph')).toBeVisible();
});

test('a stale update reports a conflict and can be saved as a new snapshot', async ({ page, context }) => {
    const first = await loadGraph(page);
    await saveGraph(page, 'Shared graph');

    const secondPage = await context.newPage();
    await secondPage.setViewportSize({ width: 1440, height: 900 });
    await loadGraph(secondPage);
    await openSavedGraph(secondPage, 'Shared graph');

    await first.getByRole('button', { name: 'Show all relation labels' }).click();
    await saveGraph(page, 'Shared graph');
    const second = explorerOf(secondPage);
    await second.getByRole('button', { name: 'Show values and types as nodes' }).click();
    await openTool(secondPage, 'Save in browser');
    const dialog = dialogOf(secondPage, 'Save graph');
    await dialog.getByRole('button', { name: 'Save', exact: true }).click();
    await expect(dialog.getByRole('note').getByText(/changed in another tab/)).toBeVisible();
    await dialog.getByRole('button', { name: 'Save as new', exact: true }).click();
    await dialog.getByLabel('Graph name').fill('Shared graph copy');
    await dialog.getByRole('button', { name: 'Save', exact: true }).click();
    await expect(dialog).toBeHidden();

    const library = await openLibrary(secondPage);
    await expect(libraryRow(library, 'Shared graph')).toBeVisible();
    await expect(libraryRow(library, 'Shared graph copy')).toBeVisible();
});
